import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const spearMountainScenarios={'spear-ordinary':'a2-p10-r3c3','spear-dedicated':'a2-p10-r3c3','mountain-ordinary':'a2-p11-r1c2','mountain-dedicated':'a2-p11-r1c2'} as const;
export type SpearMountainScenario=keyof typeof spearMountainScenarios;
export function isSpearMountainScenario(name:string):name is SpearMountainScenario{return Object.hasOwn(spearMountainScenarios,name);}
export function makeSpearMountainScenario(name:SpearMountainScenario,players:{id:string;name:string}[],options:{root?:boolean;near?:boolean;level?:number;owner?:string;incoming?:string;bonus?:number;follower?:string;prohibited?:boolean}={}){
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string],root=!!options.root,owner=options.owner??(name.startsWith('spear')?'早駆けのランカスター':'聖騎士ランスロット'),user=root?a:b;
 assignCharacter(s,a,root?owner:options.prohibited?'吟遊詩人のレスター':'侍大将のシン');assignCharacter(s,b,root?'黒騎士ガーウィン':owner);assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};const stats=gameStats(s,user);s.players[user]!.permanent!.warrior_level=20+(options.level??4)-stats.warrior_level;s.players[user]!.permanent!.spirit=20+6-stats.spirit;
 const card=takeCard(s,user,spearMountainScenarios[name]),advance=takeCard(s,a,'a2-p24-r1c2'),incoming=root?null:takeCard(s,a,options.prohibited?'呪歌':options.incoming??'a2-p24-r1c3'),prayer=takeCard(s,options.bonus?a:user,'必勝の祈り'),evade=takeCard(s,b,'見切る'),fate=takeCard(s,c,'命運凶変'),guard=options.follower?takeCard(s,root?b:a,options.follower):null;
 for(const id of [a,b,c])trimHand(s,id,card,advance,...(incoming?[incoming]:[]),prayer,evade,fate,...(guard?[guard]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(options.bonus??1)},r=transition(s,input,e);if(!r.ok)throw Error(`SPEAR_MOUNTAIN_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('SPEAR_MOUNTAIN_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('SPEAR_MOUNTAIN_IDS');}
 for(const id of [a,b,c,d]){if(guard&&id===(root?b:a))act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:guard});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(options.near??name.startsWith('mountain')){act(a,{type:'APPROACH',targetId:b,cardInstanceId:advance});for(let n=0;n<100&&s.windows?.length;n++){const w=s.windows.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'});}}
 if(root)return s;act(a,{type:'ATTACK',cardInstanceId:incoming!,targetIds:[b],dedicated:!!options.prohibited});let boosted=false;for(let n=0;n<300;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;if(options.bonus&&!boosted&&w.kind==='effect-level'){act(a,{type:'PLAY_REACTION',cardInstanceId:prayer,mode:'effect-plus',targetActionId:w.continuation.id});boosted=true;}else act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('SPEAR_MOUNTAIN_WINDOW');
}
